# Script name: 09_Reviewer_master_results.R
# ==============================================================================
# Title: Reviewer-facing integration of statistical results
#
# Author: Sergio Pérez Oliveira
#
# Purpose:
#   Integrate the final reviewer-revision outputs from scripts 03-08 into a
#   single machine-readable master table without redefining or recomputing any
#   testing family.
#
# IMPORTANT:
#   - Existing p_adj values are carried forward exactly as generated by the
#     originating analysis scripts.
#   - This script DOES NOT pool p-values across families and DOES NOT create a
#     post hoc global correction.
#   - Sensitivity models and external meta-analysis rows are explicitly labelled
#     and do not receive a new within-study multiplicity adjustment here.
#
# Outputs:
#   results/reviewer_revision/09_reviewer_master_results.csv
#   results/reviewer_revision/09_testing_family_summary.csv
#   results/reviewer_revision/09_correction_stable_results.csv
#   results/reviewer_revision/09_nominal_not_correction_stable.csv
# ==============================================================================

revision_dir <- file.path("results", "reviewer_revision")

if (!dir.exists(revision_dir)) {
  stop(
    "results/reviewer_revision/ does not exist. Run scripts 03-08 first.",
    call. = FALSE
  )
}

required_files <- c(
  "03_IA_frequency_master_results.csv",
  "04_CAG_omnibus_master_results.csv",
  "04_CAG_pairwise_master_results.csv",
  "05_HTT_BDI_logistic_results.csv",
  "05_CAG_multinomial_global_results.csv",
  "06_onset_IA_master_results.csv",
  "06_onset_CAG_global_results.csv",
  "06_duration_STR_master_results.csv",
  "06_duration_APOE_master_results.csv",
  "08_HTT_meta_study_effects.csv",
  "08_HTT_meta_summary.csv"
)

missing_files <- required_files[
  !file.exists(file.path(revision_dir, required_files))
]

if (length(missing_files) > 0L) {
  stop(
    paste(
      "Missing required reviewer-revision output(s):",
      paste(missing_files, collapse = ", ")
    ),
    call. = FALSE
  )
}

read_revision <- function(filename) {
  readr::read_csv(
    file.path(revision_dir, filename),
    show_col_types = FALSE,
    progress = FALSE
  )
}

# ------------------------------------------------------------------------------
# Common schema
# ------------------------------------------------------------------------------

master_cols <- c(
  "source_script",
  "source_file",
  "test_id",
  "family_id",
  "analysis_role",
  "cohort",
  "outcome",
  "predictor",
  "contrast",
  "n_total",
  "effect_type",
  "effect_estimate",
  "ci_low",
  "ci_high",
  "p_raw",
  "p_adj",
  "adjustment_method",
  "secondary_p_name",
  "secondary_p_value",
  "significant_raw",
  "significant_adjusted",
  "correction_status",
  "notes"
)

standardize_master <- function(df) {
  missing <- setdiff(master_cols, names(df))
  for (nm in missing) {
    df[[nm]] <- NA
  }

  df |>
    dplyr::select(dplyr::all_of(master_cols)) |>
    dplyr::mutate(
      n_total = suppressWarnings(as.integer(n_total)),
      effect_estimate = suppressWarnings(as.numeric(effect_estimate)),
      ci_low = suppressWarnings(as.numeric(ci_low)),
      ci_high = suppressWarnings(as.numeric(ci_high)),
      p_raw = suppressWarnings(as.numeric(p_raw)),
      p_adj = suppressWarnings(as.numeric(p_adj)),
      secondary_p_value = suppressWarnings(as.numeric(secondary_p_value)),
      significant_raw = dplyr::case_when(
        !is.na(p_raw) ~ p_raw < 0.05,
        TRUE ~ as.logical(significant_raw)
      ),
      significant_adjusted = dplyr::case_when(
        !is.na(p_adj) ~ p_adj < 0.05,
        TRUE ~ as.logical(significant_adjusted)
      )
    )
}

