# 03: categorical IA families
# ------------------------------------------------------------------------------

r03 <- read_revision("03_IA_frequency_master_results.csv") |>
  dplyr::transmute(
    source_script = "03_Genotype_stats.R",
    source_file = "03_IA_frequency_master_results.csv",
    test_id,
    family_id,
    analysis_role = dplyr::if_else(
      family_id == "A_IA_DIAGNOSIS",
      "prespecified categorical IA comparison",
      "exploratory categorical IA comparison"
    ),
    cohort = analysis,
    outcome = "Intermediate-allele carrier status",
    predictor = gene,
    contrast,
    n_total,
    effect_type = "odds_ratio",
    effect_estimate = odds_ratio,
    ci_low = conf_low,
    ci_high = conf_high,
    p_raw,
    p_adj,
    adjustment_method,
    secondary_p_name = NA_character_,
    secondary_p_value = NA_real_,
    significant_raw,
    significant_adjusted,
    correction_status = dplyr::case_when(
      !is.na(p_adj) & p_adj < 0.05 ~ "correction-stable",
      !is.na(p_raw) & p_raw < 0.05 ~ "nominal only; not correction-stable",
      TRUE ~ "not significant"
    ),
    notes = effect_definition
  ) |>
  standardize_master()

