normalize_duration <- function(filename, role) {
  read_revision(filename) |>
    dplyr::transmute(
      source_script = "06_Survival_age_analysis.R",
      source_file = filename,
      test_id,
      family_id,
      analysis_role = role,
      cohort = cohort_scope,
      outcome = "Observed disease duration",
      predictor,
      contrast,
      n_total,
      effect_type = "rank_biserial",
      effect_estimate = rank_biserial,
      ci_low = NA_real_,
      ci_high = NA_real_,
      p_raw,
      p_adj,
      adjustment_method,
      secondary_p_name = NA_character_,
      secondary_p_value = NA_real_,
      significant_raw,
      significant_adjusted,
      correction_status = dplyr::case_when(
        !is.na(p_adj) & p_adj < 0.05 ~ "correction-stable",
        !is.na(p_raw) & p_raw < 0.05 ~ "nominal only; not correction-stable",
        TRUE ~ "not significant"
      ),
      notes = paste0(
        "Cross-sectional observed duration; median difference=",
        signif(median_difference, 4),
        "; not a progression/time-to-event analysis"
      )
    ) |>
    standardize_master()
}

