# ------------------------------------------------------------------------------
# Bind all inferential rows
# ------------------------------------------------------------------------------

master_results <- dplyr::bind_rows(
  r03,
  r04_omnibus,
  r04_pairwise,
  r05_htt,
  r05_global,
  r06_onset_ia,
  r06_onset_global,
  r06_duration_str,
  r06_duration_apoe,
  r08_studies,
  r08_summary
) |>
  dplyr::arrange(
    source_script,
    family_id,
    dplyr::coalesce(p_adj, p_raw),
    p_raw
  )

readr::write_csv(
  master_results,
  file.path(revision_dir, "09_reviewer_master_results.csv")
)

# ------------------------------------------------------------------------------
# Family-level audit summary
# ------------------------------------------------------------------------------

family_summary <- master_results |>
  dplyr::filter(
    !family_id %in% c(
      "A_IA_DIAGNOSIS_SENSITIVITY",
      "EXTERNAL_HTT_META"
    )
  ) |>
  dplyr::group_by(
    source_script,
    family_id,
    adjustment_method
  ) |>
  dplyr::summarise(
    n_tests = dplyr::n(),
    n_raw_significant = sum(significant_raw %in% TRUE, na.rm = TRUE),
    n_adjusted_significant = sum(
      significant_adjusted %in% TRUE,
      na.rm = TRUE
    ),
    min_p_raw = if (all(is.na(p_raw))) NA_real_ else min(p_raw, na.rm = TRUE),
    min_p_adj = if (all(is.na(p_adj))) NA_real_ else min(p_adj, na.rm = TRUE),
    .groups = "drop"
  ) |>
  dplyr::arrange(source_script, family_id)

readr::write_csv(
  family_summary,
  file.path(revision_dir, "09_testing_family_summary.csv")
)

# ------------------------------------------------------------------------------
# Reviewer-facing subsets
# ------------------------------------------------------------------------------

correction_stable <- master_results |>
  dplyr::filter(significant_adjusted %in% TRUE) |>
  dplyr::arrange(p_adj, p_raw)

readr::write_csv(
  correction_stable,
  file.path(revision_dir, "09_correction_stable_results.csv")
)

nominal_not_stable <- master_results |>
  dplyr::filter(
    significant_raw %in% TRUE,
    !significant_adjusted %in% TRUE,
    !is.na(p_adj)
  ) |>
  dplyr::arrange(p_raw)

readr::write_csv(
  nominal_not_stable,
  file.path(revision_dir, "09_nominal_not_correction_stable.csv")
)

